def merge_headers(base: dict, override: dict) -> dict:
    merged = {}
    for k, v in base.items():
        merged[k] = v
    for k, v in override.items():
        merged[k] = v
    return merged

def extract_cookies(headers: dict) -> dict:
    cookies = {}
    for value in headers.get('Set-Cookie', '').split(','):
        value = value.strip()
        if '=' in value:
            name, _, rest = value.partition('=')
            cookies[name.strip()] = rest.split(';')[0].strip()
    return cookies

def redact_auth(url: str) -> str:
    if '@' not in url:
        return url
    scheme_rest = url.split('@', 1)
    if '//' in scheme_rest[0] and ':' in scheme_rest[0].split('//')[-1]:
        prefix = scheme_rest[0].rsplit(':', 1)[0]
        return f'{prefix}:***@{scheme_rest[1]}'
    return url
